mapper.insert:
insert into orders(
    user_id, order_num, total_price, order_status,
    address, delete_status, add_time, ship_time, complete_time, return_reason, return_address
) values (
         #{userId}, #{orderNum}, #{totalPrice}, #{orderStatus},
         #{address}, #{deleteStatus}, #{addTime}, #{shipTime}, #{completeTime}, #{returnReason}, #{returnAddress}
     )

mapper.select:
select *
from orders
where user_id = #{userId}
  and delete_status = 0
order by add_time desc
limit #{start}, #{size}

select *
from orders
where delete_status = 0

    and order_status = #{status}

order by add_time desc
limit #{start}, #{size}

mapper.update:
update orders
set order_status = #{status}
where id = #{orderId}

update orders
set order_status = #{status},
    ship_time    = #{shipTime}
where id = #{orderId}

update orders
set order_status  = #{status},
    complete_time = #{completeTime}
where id = #{orderId}

update orders
set order_status   = #{status},
    return_reason  = #{returnReason},
    return_address = #{returnAddress}
where id = #{orderId}

mapper.select:
select count(1)
from order_detail d
         join goods g on g.id = d.goods_id
where d.order_id = #{orderId}
  and g.owner_id = #{ownerId}
